def sprite():
    parts = ['<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">']
    for k, v in STROKE.items():
        parts.append(f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{v}</symbol>')
    for k, v in FILL.items():
        parts.append(f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="currentColor">{v}</symbol>')
    parts.append("</svg>")
    return "".join(parts)


def icon(name, cls="ic"):
    return f'<svg class="{cls}" aria-hidden="true"><use href="#i-{name}"/></svg>'
